class TokenBucket:
    def __init__(self, rate, cap):
        self.rate, self.cap = rate, cap
        self.tokens, self.ts = cap, time.monotonic()
    def allow(self):
        now = time.monotonic()
        self.tokens = min(self.cap, self.tokens + (now - self.ts) * self.rate)
        self.ts = now
        if self.tokens >= 1:
            self.tokens -= 1
            return True
        return False
